<?php
declare(strict_types=1);namespace Atlas\Platform\PatientResources\Repositories;final class WordPressPatientResourceAccessRepository implements PatientResourceAccessRepository{private string $r;private string $v;public function __construct(private object $db){$this->r=$db->prefix.'atlas_resources';$this->v=$db->prefix.'atlas_resource_versions';}public function isPublishedPatientEducationVersion(string $version,string $org):bool{$id=$this->db->get_var($this->db->prepare("SELECT v.id FROM `{$this->v}` v INNER JOIN `{$this->r}` r ON r.id=v.resource_id WHERE v.id=%s AND v.review_status='published' AND r.resource_type='patient_education' AND (r.scope IN ('platform','public') OR (r.scope='organization' AND r.organization_id=%s)) LIMIT 1",$version,$org));return is_string($id)&&$id!=='';}}
